package com.example.riskplatform.service.mq;import com.example.riskplatform.config.RabbitConfig;import com.example.riskplatform.service.RiskEngineService;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor @Slf4j @ConditionalOnProperty(name="app.mq.enabled",havingValue="true")public class RabbitRiskTaskDispatcher implements RiskTaskDispatcher{private final RabbitTemplate rabbit;private final RiskEngineService engine;public void dispatch(Long id){try{rabbit.convertAndSend(RabbitConfig.EXCHANGE,RabbitConfig.ROUTING_KEY,id);}catch(Exception e){// 代理不可达时降级为同步执行，保证指标风险检测不中断（部署 RabbitMQ 后自动切回异步）
log.warn("RabbitMQ 不可达，降级为同步风险检测: {}", e.getMessage());engine.evaluateMetric(id);}}}
